import { useMutation } from '@tanstack/react-query';
import { shopApi } from '~/entities/shop/api/shop-api';
import { Place } from '~/entities/shop/model/types';
import { CBDCAxiosError } from '~/shared/@types/error';
import { MutationOptions } from '~/shared/@types/query';

export const useGetShopListMutation = (options?: MutationOptions<string | void, CBDCAxiosError, Place[]>) => {
  const mutation = useMutation<Place[], CBDCAxiosError, string | void>({
    ...options,
    mutationFn: (placeId: string | void) => shopApi.getShopList(placeId),
  });

  return {
    ...mutation,
  };
};
